import pandas as pd

def clean(df):
    df = df.copy()
    for col in ['species', 'island', 'sex']:
        if col in df.columns:
            df[col] = df[col].astype('string').str.strip()
    if 'island' in df.columns:
        df['island'] = df['island'].replace({'Torgerson': 'Torgersen', 'Bisco': 'Biscoe'})
    if 'sex' in df.columns:
        df['sex'] = df['sex'].str.lower()
    for col in ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'body_mass_g', 'year']:
        if col in df.columns:
            s = df[col].astype('string').str.replace(',', '', regex=False).str.strip()
            df[col] = pd.to_numeric(s, errors='coerce')
    if 'body_mass_g' in df.columns:
        mask = df['body_mass_g'].notna() & ((df['body_mass_g'] < 2500) | (df['body_mass_g'] > 6500))
        df.loc[mask, 'body_mass_g'] = float('nan')
    if 'bill_length_mm' in df.columns:
        mask = df['bill_length_mm'].notna() & ((df['bill_length_mm'] < 30) | (df['bill_length_mm'] > 60))
        df.loc[mask, 'bill_length_mm'] = float('nan')
    if 'flipper_length_mm' in df.columns:
        mask = df['flipper_length_mm'].notna() & ((df['flipper_length_mm'] < 170) | (df['flipper_length_mm'] > 235))
        df.loc[mask, 'flipper_length_mm'] = float('nan')
    return df

def answer(df):
    d = clean(df)
    d = d[d['species'].astype(str).str.strip() == 'Adelie']
    d = d.dropna(subset=['island', 'bill_length_mm'])
    means = d.groupby('island')['bill_length_mm'].mean()
    return {str(k): float(v) for k, v in means.items()}
